{:else}<div class="mt-9 grid gap-10 lg:grid-cols-[1fr_20rem]">
 <section class="min-w-0"><div class="mb-7 flex items-center gap-2 border-b border-base-300 pb-4"><BookOpen size={20}/><h2 class="text-xl font-semibold">Student handover</h2></div><article class="prose prose-sm max-w-none prose-headings:font-semibold prose-a:text-primary">{@html handover}</article></section>
 <aside class="min-w-0 border-t border-base-300 pt-7 lg:border-t-0 lg:border-l lg:pl-8 lg:pt-0"><div class="flex items-center justify-between"><h2 class="text-xl font-semibold">{$session.lab.team.name}</h2><a href="/teams/" class="link text-sm">Change</a></div><p class="mt-3 flex items-center gap-2 text-sm text-base-content/70"><Clock size={16}/>Ends at {$session.meeting?date($session.meeting.expires):'—'}</p>
